const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var prescott = ee.Geometry.Point([-112.4682, 34.5400]);
  var startDate = '2017-06-01';
  var endDate = '2017-06-30';

  // 2. Data Acquisition
  var collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterBounds(prescott)
    .filterDate(startDate, endDate)
    .select('temperature_2m');  // in Kelvin

  var count = collection.size();
  var countInfo = count.getInfo();
  print('June 2017 hourly images:', countInfo);

  if (countInfo === 0) {
    print('No temperature data found for June 2017.');
    print('<answer>C1</answer>');
    return;
  }

  // 3. Compute maximum temperature over the month
  var maxTempK = collection.max();  // maximum Kelvin value for each pixel over the month
  // Convert to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  var maxTempF = maxTempK.expression(
    '(K - 273.15) * 9/5 + 32', {'K': maxTempK.select('temperature_2m')}
  ).rename('temperature_2m_f');

  // 4. Extract value at Prescott point
  var result = maxTempF.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: prescott,
    scale: 10000,  // ERA5-Land resolution is ~0.1 deg, ~11 km
    maxPixels: 1e9,
    bestEffort: true,
  });

  var pixelCount = result.get('temperature_2m_f_count');
  var maxF = result.get('temperature_2m_f_max');

  var pixelCountInfo = pixelCount.getInfo();
  var maxFInfo = maxF.getInfo();

  print('Valid pixels at point:', pixelCountInfo);
  print('Maximum temperature (F) in June 2017:', maxFInfo);

  // 5. Validate and decide
  if (pixelCountInfo === 0) {
    print('No valid pixels after processing.');
    print('<answer>C2</answer>');
  } else if (maxFInfo === null || maxFInfo === undefined || isNaN(maxFInfo)) {
    print('Invalid temperature value.');
    print('<answer>C3</answer>');
  } else {
    // Check if maximum temperature exceeds 100°F
    if (maxFInfo > 100) {
      print('<answer>A</answer>');
    } else {
      print('<answer>B</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
